package in.tucor.api.buyer; import org.springframework.data.jpa.repository.*; import jakarta.persistence.LockModeType; import java.util.*; public interface MarketListingRepository extends JpaRepository<MarketListing,UUID>{List<MarketListing> findAllByOrderByCreatedAtDesc();@Query("select l from MarketListing l join User u on u.id=l.sellerId where l.status in :statuses and u.status='ACTIVE' and u.emailVerified=true order by l.createdAt desc") List<MarketListing> findByStatusInOrderByCreatedAtDesc(Collection<String> statuses);List<MarketListing> findBySellerIdOrderByCreatedAtDesc(UUID sellerId);Optional<MarketListing> findBySellerIdAndPublicId(UUID sellerId,String publicId);Optional<MarketListing> findByPublicId(String publicId); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select l from MarketListing l where l.publicId=:publicId") Optional<MarketListing> findByPublicIdForUpdate(String publicId); long countByStatusIn(Collection<String> statuses);}
